/**
 * Minimal HTML to Markdown converter, tuned for this course's markup.
 * No dependencies: the pages are generated by us, so the structure is known.
 *
 * Exports: convert(html) -> { title, eyebrow, lead, sections }
 */

const VOID = new Set([
  "br", "hr", "img", "input", "meta", "link", "source",
  "area", "base", "col", "embed", "param", "track", "wbr",
]);

const TAG_RE =
  /<!--[\s\S]*?-->|<\/([a-zA-Z][\w-]*)\s*>|<([a-zA-Z][\w-]*)((?:[^>"']|"[^"]*"|'[^']*')*)>/g;

function parseAttrs(raw) {
  const attrs = {};
  const re = /([a-zA-Z0-9:_-]+)(?:\s*=\s*"([^"]*)")?/g;
  let m;
  while ((m = re.exec(raw))) {
    if (m[1]) attrs[m[1].toLowerCase()] = m[2] === undefined ? "" : m[2];
  }
  return attrs;
}

function parse(html) {
  const root = { tag: "root", attrs: {}, children: [] };
  const stack = [root];
  let last = 0;
  let m;

  const pushText = (s) => {
    if (s) stack[stack.length - 1].children.push({ tag: "#text", text: s });
  };

  TAG_RE.lastIndex = 0;
  while ((m = TAG_RE.exec(html))) {
    if (m.index > last) pushText(html.slice(last, m.index));
    last = TAG_RE.lastIndex;

    if (m[0].startsWith("<!--")) continue;

    if (m[1]) {
      const tag = m[1].toLowerCase();
      for (let i = stack.length - 1; i > 0; i--) {
        if (stack[i].tag === tag) {
          stack.length = i;
          break;
        }
      }
      continue;
    }

    const tag = m[2].toLowerCase();
    let raw = m[3] || "";
    const selfClosing = /\/\s*$/.test(raw);
    if (selfClosing) raw = raw.replace(/\/\s*$/, "");

    const node = { tag, attrs: parseAttrs(raw), children: [] };
    stack[stack.length - 1].children.push(node);
    if (!VOID.has(tag) && !selfClosing) stack.push(node);
  }

  if (last < html.length) pushText(html.slice(last));
  return root;
}

/* ── entities ─────────────────────────────────────────────── */

function decode(s) {
  return String(s)
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&");
}

/* ── tree helpers ─────────────────────────────────────────── */

function findAll(node, tag, out = []) {
  for (const child of node.children || []) {
    if (child.tag === tag) out.push(child);
    findAll(child, tag, out);
  }
  return out;
}

function find(node, tag) {
  return findAll(node, tag)[0] || null;
}

function hasClass(node, name) {
  return String(node.attrs.class || "").split(/\s+/).includes(name);
}

/** Raw text, whitespace preserved (for <pre>). */
function rawText(node) {
  if (node.tag === "#text") return decode(node.text);
  return (node.children || []).map(rawText).join("");
}

/** Collapsed text (for headings and cells). */
function textOf(node) {
  return rawText(node).replace(/\s+/g, " ").trim();
}

/* ── inline rendering ─────────────────────────────────────── */

function inline(node) {
  if (node.tag === "#text") return decode(node.text).replace(/\s+/g, " ");
  if (node.tag === "br") return "  \n";
  if (node.tag === "code") return "`" + rawText(node).trim() + "`";
  if (node.tag === "strong" || node.tag === "b") {
    return "**" + inlineChildren(node).trim() + "**";
  }
  if (node.tag === "em" || node.tag === "i") {
    return "*" + inlineChildren(node).trim() + "*";
  }
  if (node.tag === "a") {
    const href = node.attrs.href || "";
    const label = inlineChildren(node).trim();
    return label ? "[" + label + "](" + href + ")" : "";
  }
  if (node.tag === "span") {
    if (hasClass(node, "ic") || hasClass(node, "spacer")) return "";
    if (hasClass(node, "mark")) {
      // The option letter. Render as plain "A." and let the caller decide styling.
      return inlineChildren(node).trim() + ". ";
    }
    return inlineChildren(node);
  }
  if (node.tag === "pre") return "";
  return inlineChildren(node);
}

function inlineChildren(node) {
  return (node.children || []).map(inline).join("");
}

/** Inline content of a block, with stray spaces tidied. */
function inlineBlock(node) {
  return inlineChildren(node)
    .replace(/[ \t]+/g, " ")
    .replace(/ *\n */g, "\n")
    .trim();
}

module.exports = {
  parse,
  decode,
  findAll,
  find,
  hasClass,
  rawText,
  textOf,
  inline,
  inlineBlock,
};
